from more_itertools import interleave_evenly, sliced, numeric_range
from decimal import Decimal
from fractions import Fraction
from datetime import datetime, timedelta

for inputs in ([], [[], []], [[], [1, 2, 3], []]):
    expected = [item for seq in inputs for item in seq]
    assert list(interleave_evenly(inputs)) == expected
    assert list(interleave_evenly(inputs, lengths=list(map(len, inputs)))) == expected
assert list(interleave_evenly([iter(()), iter(())], lengths=[0, 0])) == []
for strict in (False, True):
    for seq in ([], [1, 2, 3]):
        try:
            sliced(seq, -1, strict=strict)
        except ValueError:
            pass
        else:
            raise AssertionError('negative size accepted')
    assert list(sliced([1, 2, 3], 0, strict=strict)) == []

for start in range(-4, 5):
    for stop in range(-4, 5):
        for step in (-3, -1, 1, 3):
            assert list(reversed(numeric_range(start, stop, step))) == list(range(start, stop, step))[::-1]
for typ in (float, Decimal, Fraction):
    for start, stop, step in [('0', '1', '0.1'), ('1', '0', '-0.1'), ('0.2', '0.3', '0.1'), ('0', '0', '0.1'), ('1', '0', '0.1')]:
        r = numeric_range(*(typ(x) for x in (start, stop, step)))
        assert list(reversed(r)) == list(r)[::-1], (r, list(reversed(r)), list(r))
for start, stop, step in [(datetime(2020, 1, 1), datetime(2020, 1, 3), timedelta(hours=7)), (datetime.min, datetime.min, timedelta(days=1)), (datetime.min, datetime.min + timedelta(days=2), timedelta(days=1))]:
    r = numeric_range(start, stop, step)
    assert list(reversed(r)) == list(r)[::-1]
print('Targeted regression checks passed')
